/* Focused application of the existing overview Enter/Back/Forward/direct-return protocol.
 * Product bytes are overlaid at their exact future public URLs. Only45 listed files
 * are intercepted; the unchanged overview assets and shared teachers are live GETs.
 * This is single-card regression, not a fresh certificate for unrelated workbenches.
 */
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),pw=require('playwright');
const root=path.resolve(__dirname,'..'),engine=process.env.OVERVIEW_BROWSER||'chromium',out=path.join(root,'qa-output','overview-card-'+engine),site='https://haihao0307.github.io/guilin-dem-pipeline/',base=site+'kaopu-human-overview/',target=site+'kaopu-unified-human-workbench/';fs.mkdirSync(out,{recursive:true});const manifest=JSON.parse(fs.readFileSync(path.join(root,'DEPLOYMENT-45-MANIFEST.json'))),allowed=new Map(manifest.files.map(x=>[site+x.path,x])),oldHTML=fs.readFileSync(path.join(root,'fixtures/public-overview-index.html'),'utf8');
let browser,page;const report={engine,passed:false,scope:'Only changed shared-stage card, existing navigation protocol; 44 runtime bytes frozen',errors:[],crashes:0,intercepted:[],screens:[],pageTransitions:[]};const save=()=>fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));
const ready=async()=>{await page.waitForFunction(()=>!!window.fullCommonWorkbench);if(!(await page.evaluate(()=>fullCommonWorkbench.diagnostics().ready))){await page.locator('#load-model').click();await page.waitForFunction(()=>fullCommonWorkbench.diagnostics().ready&&!fullCommonWorkbench.diagnostics().busy,null,{timeout:240000});}};
const hash=()=>page.evaluate(async()=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',fullCommonWorkbench.positions().buffer))].map(x=>x.toString(16).padStart(2,'0')).join(''));
(async()=>{browser=await pw[engine].launch(engine==='webkit'?{headless:true}:{headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']});const context=await browser.newContext({viewport:{width:1440,height:900}});
 report.candidateOverlay=!process.env.PUBLIC_OVERVIEW;
 if(report.candidateOverlay)await context.route(site+'**',async route=>{let url=new URL(route.request().url());url.search='';url.hash='';if(url.pathname.endsWith('/'))url.pathname+='index.html';const row=allowed.get(url.href);if(!row)return route.continue();const body=fs.readFileSync(path.join(root,'deployment',row.path));assert.equal(crypto.createHash('sha256').update(body).digest('hex'),row.sha256);const ext=path.extname(row.path),contentType={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json'}[ext]||'application/octet-stream';report.intercepted.push(row.path);await route.fulfill({status:200,body,contentType});});
 page=await context.newPage();page.on('pageerror',e=>report.errors.push(e.message));page.on('crash',()=>report.crashes++);await page.goto(base,{waitUntil:'networkidle'});assert.equal(await page.title(),'KAOPU · 统一创作工作台');
 const unchanged=await page.evaluate(old=>{const d=new DOMParser().parseFromString(old,'text/html'),attrs=n=>[n.tagName,n.getAttribute('href'),n.getAttribute('src'),n.getAttribute('width'),n.getAttribute('height'),n.getAttribute('alt')];return JSON.stringify([...d.querySelectorAll('a,img,link,script')].map(attrs))===JSON.stringify([...document.querySelectorAll('a,img,link,script')].map(attrs));},oldHTML);assert(unchanged,'Existing links, images or scripts changed');assert.equal(await page.locator('iframe,canvas').count(),0);assert.equal(await page.locator('a[target="_blank"]').count(),0);
 assert.equal(await page.locator('.stage-jump[href="#shared-stage"] strong').textContent(),'全参数兼容测试');
 const expected={'.eyebrow':'ONE PERSON / 全参数兼容测试','.status':'成人基础 · 参数测试','time':'2026.10.07','#shared-limit':'三个来源的参数通路已接入。婴幼儿耳部与牙列、极端表情接触仍未验收；皮肤、照片视频拟合及毛发另列。完整参数可保存恢复，通用导出是当前姿态快照。'};for(const[selector,text]of Object.entries(expected))assert.equal(await page.locator('#shared-stage '+selector).textContent(),text);assert.equal(await page.locator('#shared-stage time').getAttribute('datetime'),'2026-10-07');assert.equal(await page.locator('#shared-stage .shared-visual a').getAttribute('href'),'../kaopu-unified-human-workbench/');
 for(const size of[{width:2048,height:1040},{width:1440,height:900}]){await page.setViewportSize(size);await page.locator('#shared-stage').scrollIntoViewIfNeeded();await page.locator('#shared-stage img').evaluate(i=>i.decode());assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));const rect=await page.locator('#shared-stage .shared-visual a').boundingBox();assert(rect.width>=44&&rect.height>=44);await page.locator('#shared-stage').screenshot({path:path.join(out,'shared-card-'+size.width+'.png')});report.screens.push(size);}
 // Exact keyboard and history operations used by the existing overview QA.
 const link=page.locator('#shared-stage .shared-visual a');await link.focus();assert(await link.evaluate(a=>a===document.activeElement));await Promise.all([page.waitForURL(target,{waitUntil:'domcontentloaded'}),page.keyboard.press('Enter')]);assert.equal(context.pages().length,1);await ready();const neutral=await hash();assert.equal(neutral,'fbc056553c1731b790769124bee121554f0800400271eaf564a0ad5e6f458571');
 await page.locator('.group-select').selectOption('gnm.identity');const input=page.locator('[data-parameter="gnm.identity:0"] input[type=number]');await input.scrollIntoViewIfNeeded();await input.fill('0.2');await input.press('Tab');await page.waitForFunction(()=>fullCommonWorkbench.state().gnm.identity[0]===.2);const changed=await hash();assert.notEqual(changed,neutral);const [download]=await Promise.all([page.waitForEvent('download'),page.locator('[data-action=save]').click()]);const archive=fs.readFileSync(await download.path());await page.screenshot({path:path.join(out,'entered-common-real-control.png')});
 await page.goBack({waitUntil:'domcontentloaded'});await page.locator('#title').waitFor();assert.equal(page.url(),base);await page.goForward({waitUntil:'domcontentloaded'});assert.equal(page.url(),target);await ready();await page.locator('#common-profile-file').setInputFiles({name:'public-common-regression.json',mimeType:'application/json',buffer:archive});await page.waitForFunction(()=>fullCommonWorkbench.state().gnm.identity[0]===.2);assert.equal(await hash(),changed);await page.locator('#overview-back').click();await page.waitForURL(base,{waitUntil:'domcontentloaded'});await page.locator('#title').waitFor();assert.equal(context.pages().length,1);assert.equal(await page.locator('canvas,iframe').count(),0);await page.reload({waitUntil:'domcontentloaded'});await page.locator('#shared-stage').scrollIntoViewIfNeeded();await page.locator('#shared-stage').screenshot({path:path.join(out,'returned-shared-card.png')});report.entryReturn={keyboard:true,back:true,forward:true,directReturn:true,archiveGeometryExact:true,neutralSHA256:neutral,changedSHA256:changed};assert.deepEqual(report.errors,[]);assert.equal(report.crashes,0);report.passed=true;report.version=browser.version();save();await browser.close();
})().catch(async e=>{report.failure=e.stack||String(e);save();console.error(e);try{await page?.screenshot({path:path.join(out,'failure.png'),timeout:5000})}catch{}await browser?.close();process.exit(1)});
